def run(context):
    # Analyze and summarize the latest quarterly results
    summary = {}
    for record in context:
        symbol = record['symbol']
        verdict = record['verdict']
        summary[symbol] = verdict
    return {'summary': summary}

def run(context):
    latest_dates = context['inputs']['latest_dates']
    expected_timeframes = context['inputs']['expected_timeframes']
    freshness_status = {}
    for table, date_info in latest_dates.items():
        freshness_status[table] = 'Fresh' if date_info >= expected_timeframes[table] else 'Stale'
    return {'freshness_status': freshness_status}

def run(context):
    summary = {}
    # Analyze winning signals
    winner_patterns = context[context['hit_target'] == True]
    if not winner_patterns.empty:
        summary['winner_patterns'] = winner_patterns['symbol'].value_counts().to_dict()
    # Analyze failure signals
    failure_patterns = context[context['hit_stop'] == True]
    if not failure_patterns.empty:
        summary['failure_patterns'] = failure_patterns['symbol'].value_counts().to_dict()
    return summary
